local _, ns = ...
if ns.LOCALE ~= "deDE" then return end
local L = ns.L

-- Options/Welcome.lua: What's New, by version (WN<id>_<n>), newest first; beside Locales/deDE.lua.
L["WN30_1_TITLE"] = "Korrekturen an den Aktionsleisten"
L["WN30_1_TEXT"] = "Zwischen den Tasten der Hauptleiste blitzen beim Seitenwechsel, etwa mit Verstohlenheit oder Druidengestalten, keine goldenen Trennlinien mehr auf, und der goldene Rand einer eingeschalteten Fähigkeit ist wieder vollständig."
L["WN30_2_TITLE"] = "Lehrer"
L["WN30_2_TEXT"] = "Trainieren im klassischen Lehrerfenster lernt die gewählte Fertigkeit oder das Rezept wieder, und dein Geld darunter wird in voller Helligkeit gezeigt."
L["WN29_1_TITLE"] = "Ein klassisches Vermächtnisfenster"
L["WN29_1_TEXT"] = "Die Vermächtnis-Schaltfläche und -Taste öffnen ein klassisches Vermächtnisfenster: die Belohnungsleiste und die Herausforderungen auf alten Fertigkeitsbalken, mit Suche und Filter, und die Vermächtnisbäume im alten Talentfenster. Standardmäßig an; abschalten in den Optionen (/fcui) unter Charakter und Zauber."
L["WN29_2_TITLE"] = "Deine eigenen Layouts bleiben deine"
L["WN29_2_TEXT"] = "Mit abgeschaltetem Addon stehen die Aktionsleisten in deinen eigenen Bearbeitungsmodus-Layouts nicht mehr an den Stellen der klassischen Leiste. Dort früher gespeicherte Stellen werden beim nächsten Druck auf UI neu laden in den Optionen (/fcui) oder mit /fcui off zurückgegeben."
L["WN29_3_TITLE"] = "Korrekturen"
L["WN29_3_TEXT"] = "/fcui off schaltet das Addon wieder aus. Ein Klick auf ein Gildenmitglied im Kampf öffnet seine Details. Das Einstellungsfenster des Spiels zeigt nach einem Kampf keine Fehlerflut mehr, Questlevel bleiben mit abgeschalteter Option verborgen, und der Pfeil nach unten im Chat blinkt nicht mehr auf."
L["WN29_4_TITLE"] = "Waffenplätze"
L["WN29_4_TEXT"] = "Die Waffenplätze im Charakterfenster stehen mittig auf zwei Mulden, ohne die leere Mulde für den Fernkampfplatz."
L["WN28_1_TITLE"] = "Kürzliche Verbündete und Ignorieren"
L["WN28_1_TEXT"] = "Der Freunde-Reiter des Kontaktfensters hat neben Freunde die Reiter Kürzliche Verbündete und Ignorieren. Kürzliche Verbündete zeigt die Spieler, mit denen du zuletzt in einer Gruppe warst, mit einer Suchzeile; Ignorieren zeigt die Spieler, die du ignorierst."
L["WN28_2_TITLE"] = "Wieder das klassische Kontaktfenster"
L["WN28_2_TEXT"] = "Seit dem letzten Spielupdate öffneten O und der Gildenknopf das neue Kontaktfenster des Spiels. Sie öffnen wieder das klassische, seine Reiter sitzen richtig, und der Schlachtzugsreiter ist zurück."
L["WN28_3_TITLE"] = "Korrekturen nach dem Spielupdate"
L["WN28_3_TEXT"] = "Die Combopunkte zeigen wieder alle fünf klassischen Kugeln. Der dunkle Streifen über dem Charaktermodell und der dunkle Kasten auf den Eintragsseiten der Gruppensuche sind weg, der Sortierknopf funktioniert im Ein-Taschen-Modus, und die Gruppensuche springt nicht mehr, wenn sie im Kampf geöffnet wird."
L["WN28_4_TITLE"] = "Beutefenster und Taschen"
L["WN28_4_TEXT"] = "Mit ausgeschaltetem Beutefenster zeigt das Beutefenster des Spiels keine zwei weißen Quadrate mehr in seinen Ecken. Der Sortierknopf der Taschen passt neben das Suchfeld."
L["WN27_1_TITLE"] = "Weniger Hintergrundarbeit"
L["WN27_1_TEXT"] = "Die Namensplaketten werden nur noch neu angeordnet, wenn sich eine Namensplaketten-Einstellung ändert, nicht mehr bei jeder Einstellung, die das Spiel oder ein anderes Addon ändert. Die Koordinaten der Minikarte werden nur noch gemessen, wenn sie sich ändern. Am Aussehen ändert sich nichts."
L["WN26_1_TITLE"] ="Klassenfarben je Fenster"
L["WN26_1_TEXT"] = "Gesundheit in Klassenfarbe und Namensfeld in Klassenfarbe sind standardmäßig aus; schalte sie in den Optionen (/fcui) unter Einheitenfenster ein. Beide haben jetzt darunter eine Auswahl der Fenster: Spieler, Ziel und Fokus, so kann das Ziel seine Klassenfarbe tragen, während dein eigenes Fenster bleibt, wie es war."
L["WN26_2_TITLE"] = "Namensfeldfarbe"
L["WN26_2_TEXT"] = "Eine neue Auswahl Namensfeldfarbe unter Einheitenfenster bestimmt, bei welchen Fenstern das Namensfeld die Farbe des Spiels für die Einheit annimmt (Blau für einen freundlichen Spieler). Ziel und Fokus sind angehakt, wie in Classic Era; ohne Haken bleibt das Feld schlicht. Spieler ist standardmäßig aus; schalte es in den Optionen (/fcui) ein, um dein eigenes zu färben."
L["WN26_3_TITLE"] = "Korrekturen"
L["WN26_3_TEXT"] = "Mit der dicken Gesundheitsleiste über dem Namen ist das Namensfeld des Spielerfensters nicht mehr hinter der Leiste zu sehen. Wird das Namensfeld in Klassenfarbe abgewählt, verschwindet die Farbe bei Ziel und Fokus sofort."
L["WN25_1_TITLE"] = "Greifen"
L["WN25_1_TEXT"] = "Die Greifen werden jetzt mit dem Layout des Bearbeitungsmodus gespeichert, wie die eigenen Elemente des Spiels: Jedes Layout behält seine eigenen Plätze für sie, und Speichern auf einer Spielvorlage fragt nach einem neuen Layout, das sie übernimmt. Eine nicht gespeicherte Verschiebung wird beim Schließen des Bearbeitungsmodus verworfen. Das klassische Layout in den Optionen setzt sie wieder an die Enden der Leiste."
L["WN24_1_TITLE"] = "Taschen"
L["WN24_1_TEXT"] = "Offene Taschen springen nicht mehr zur Seite, wenn du einen Gegenstand per Rechtsklick anlegst, im Kampf wie außerhalb."
L["WN23_1_TITLE"] = "Schlagtimer"
L["WN23_1_TEXT"] = "Ein Waffenwechsel im Kampf löst keinen Lua-Fehler mehr in jedem Bild aus, in dem die Schlagleiste zu sehen ist, und das Aufblitzen beim Schlag funktioniert nach dem Wechsel weiter."
L["WN22_1_TITLE"] = "Berufe"
L["WN22_1_TEXT"] = "Ein Beruf öffnet sich im klassischen Berufsfenster, und das Berufebuch ist das alte kleine im Rahmen des Zauberbuchs. Die Größentaste neben der Schließen-Taste wechselt jeweils zum vollen Fenster des Spiels."
L["WN22_2_TITLE"] = "Zauberbuch und Talente"
L["WN22_2_TEXT"] = "Eine Zauberbuch-Taste im Mikromenü, neben Charakter, öffnet das klassische Zauberbuch. Das Talentfenster des Spiels trägt den klassischen Rahmen, und die Talente-Taste öffnet es immer bei deinen Talenten."
L["WN22_3_TITLE"] = "Mikromenü und Minikarte"
L["WN22_3_TEXT"] = "Erfolge, Abenteuerführer und Behausung sind nicht mehr im Mikromenü, da 1.x keine hatte, und jede hat ein Symbol an der Minikarte. Um eine Taste zurückzuholen, entferne ihren Haken unter Mikrotasten ausblenden in den Optionen (/fcui)."
L["WN22_4_TITLE"] = "Schnellbeitritt"
L["WN22_4_TEXT"] = "Schnellbeitritt hat die Reiterleiste des Kontaktfensters verlassen. Öffne Freunde, dann Kürzliche Verbündete: Der Reiter Schnellbeitritt unter der Liste wechselt dorthin, der Reiter Kürzliche Verbündete zurück."
L["WN22_5_TITLE"] = "Leistung"
L["WN22_5_TEXT"] = "Farbthemen brauchen deutlich weniger CPU: Die gefärbten Grafiken folgen denen des Spiels nur noch, wenn sich etwas ändert, nicht in jedem Bild. Rechtsklickmenüs an Porträts, Taschen und Fenster öffnen sich ohne Ruckeln."
L["WN22_6_TITLE"] = "Makros"
L["WN22_6_TEXT"] = "Ein Zauber, der mit Umschalt-Klick aus dem klassischen Zauberbuch in ein Makro gesetzt wird, steht dort mit Name und Rang, wie aus dem Buch des Spiels; bisher war es ein Chatlink, den ein Makro nicht wirken kann. Das Makrofenster hat die Reiter von Classic Era."
L["WN22_7_TITLE"] = "Makros"
L["WN22_7_TEXT"] = "Ein Zauber, der mit Umschalt-Klick aus dem klassischen Zauberbuch in ein Makro gesetzt wird, steht dort mit Name und Rang, wie aus dem Buch des Spiels; bisher war es ein Chatlink, den ein Makro nicht wirken kann. Talente stehen ebenfalls mit ihrem Namen dort. Das Makrofenster hat die Reiter von Classic Era."
L["WN22_8_TITLE"] = "Dropdown-Menüs"
L["WN22_8_TEXT"] = "Die Dropdown-Menüs des Spiels, etwa das Statusmenü (Verfügbar, Abwesend, Beschäftigt) und das Aufspürmenü der Minikarte, haben jetzt den Eisenrahmen von Classic Era, und er umschließt ihre Symbole und Pfeile."
L["WN22_9_TITLE"] = "Ruf und Währungen"
L["WN22_9_TEXT"] = "Beide Reiter behalten die klassischen Zeilen: gleichmäßige Abstände, die alten Überschriften, eine Spalte von Balken. Eine Gruppe von Fraktionen hat ihre Plus- oder Minus-Taste, ihre Fraktionen stehen eingerückt darunter, und der Filter ist eine kleine Pfeiltaste oben rechts."
L["WN22_10_TITLE"] = "Weitere Korrekturen"
L["WN22_10_TEXT"] = "Die Reiter unter einem Fenster bleiben auf seinem unteren Rand; bei manchen Interfacegrößen wanderten sie nach oben. Ein Umschalt-Klick auf einen Beruf lässt das Zauberbuch offen, die Manazahlen eines Druiden in Gestalten folgen der Einstellung Statustext des Spiels, und der Reiter Hilfe zeigt nur die Fragen zu der Spielversion, die du spielst."
L["WN22_11_TITLE"] = "Fenster in Retail"
L["WN22_11_TEXT"] = "Die Reagenzientasche steht frei von der Latenzleiste, das Charakterfenster hat keine dünnen Linien um das Modell, das Kontaktfenster hat nur einen Wer-Reiter, und die Fensterränder sitzen wie in Forever."
L["WN21_1_TITLE"] = "Gildenliste"
L["WN21_1_TEXT"] = "Ein Klick auf ein Mitglied öffnet jetzt bei jedem Mitglied dessen Notizen und Optionen; in größeren Gilden öffnete sich bei vielen nichts. Die Liste braucht außerdem deutlich weniger CPU, solange sie offen ist."
L["WN21_2_TITLE"] = "Quests teilen"
L["WN21_2_TEXT"] = "Quest teilen im klassischen Questlog funktioniert mit einem Klick für jede Quest, auch direkt nach dem Einloggen. Bisher ging es nur bei Quests des Gebiets, das die Weltkarte zuletzt zeigte."
L["WN21_3_TITLE"] = "Fenster"
L["WN21_3_TEXT"] = "Ein geöffneter Brief hat den klassischen Fensterrahmen wie der Posteingang, und die Seitenleiste des Charakterfensters zeigt bei manchen Interfacegrößen keine dünne durchsichtige Linie mehr."
L["WN20_1_TITLE"] ="PvP-Rangdetails"
L["WN20_1_TEXT"] = "Der PvP-Reiter des Charakterfensters kann deine Rangdetails und die Belohnungen des nächsten Rangs zeigen. Klicke auf den Pfeil unten rechts im Reiter, um die Seitenleiste zu öffnen."
L["WN20_2_TITLE"] = "Addon-Tasche"
L["WN20_2_TEXT"] = "Ihr Standardplatz liegt jetzt links neben der Uhr, frei vom Auge der Gruppensuche, und sie lässt unsere eigenen Minikartensymbole wie Vermächtnis auf der Minikarte. Die Schaltfläche Klassisches Layout stellt auch verschobene Minikartenknöpfe zurück."
L["WN20_3_TITLE"] = "Andere Addons"
L["WN20_3_TEXT"] = "Teile von ClassicUI Forever, die du ausschaltest, lassen die Fenster des Spiels jetzt in Ruhe, sodass Addons, die sie umgestalten, ihr Aussehen behalten."
L["WN19_1_TITLE"] = "Minikartensymbole"
L["WN19_1_TEXT"] = "Jede Mikrotaste kann jetzt als Symbol an der Minikarte sitzen: Hake sie in den Optionen (/fcui) unter Mikrotasten an der Minikarte an. Vermächtnis und die Gruppensuche sind standardmäßig an, so ist Vermächtnis wieder erreichbar. Mit gedrückter Umschalttaste ziehst du unsere Minikartentasten um den Ring."
L["WN19_2_TITLE"] = "Questverfolgung"
L["WN19_2_TEXT"] = "Die Zielverfolgung kann die schlichte Questverfolgung aus Classic Era sein. Standardmäßig aus; zum Einschalten stelle in den Optionen (/fcui) unter Quests die Zielverfolgung auf Verfolgung aus Classic Era. Klick auf einen Titel öffnet die Quest, Umschalt-Klick beendet die Verfolgung, Rechtsklick zeigt mehr."
L["WN19_3_TITLE"] = "Optionsfenster"
L["WN19_3_TEXT"] = "Das Optionsfenster ist größer, und seine langen Listen sind jetzt Dropdowns, so gibt es weniger zu scrollen."
L["WN19_4_TITLE"] = "Bedrohung in Prozent"
L["WN19_4_TEXT"] = "Die Bedrohung in Prozent kann nur in Gruppe oder Dungeon erscheinen: Schalte in den Optionen (/fcui) unter Einheitenfenster Nur in Gruppe oder Dungeon ein. Standardmäßig aus."
L["WN19_5_TITLE"] = "Details aus Classic Era"
L["WN19_5_TEXT"] = "Der Tooltip der Spielmenütaste hat die Beschreibungen aus Classic Era, Dropdown-Menüs haben den Eisenrahmen aus Classic Era, und Mikrotasten werden bei geöffnetem Spielmenü nicht mehr grau."
L["WN19_6_TITLE"] = "Fehlerbehebungen"
L["WN19_6_TEXT"] = "Optionen zurücksetzen behält die klassisch großen Leisten, eigene Designs färben die Reiter der Optionen ganz, die Grafik der klassischen Leiste bleibt im Layout ClassicUI Forever sichtbar, die Optionstaste überdeckt die Verfolgungslupe nicht mehr, und ist Minikarte abgewählt, bleiben von einem anderen Addon ausgeblendete Minikartensymbole ausgeblendet."
L["WN18_1_TITLE"] = "Berufe"
L["WN18_1_TEXT"] = "Im Berufsfenster kannst du jetzt ein Rezept verfolgen (seine Reagenzien stehen in der Zielverfolgung), nach Ausrüstungsplatz filtern und deinen Beruf mit dem Kettenglied neben dem Titel im Chat verlinken. Die Berufetaste öffnet wieder das Berufsbuch."
L["WN18_2_TITLE"] = "Elitedrachen"
L["WN18_2_TEXT"] = "Elitegegner können auf der Namensplakette einen goldenen Drachen um ihre Stufe zeigen, seltene einen silbernen: Schalte in den Optionen (/fcui) unter Namensplaketten Elitedrachen ein. Mit einem eigenen Design halten Design für Elitefenster ignorieren und Design für Plakettendrachen ignorieren unter Eigenes Design die Drachen golden und silbern. Alles standardmäßig aus."
L["WN18_3_TITLE"] = "Kampfleuchten"
L["WN18_3_TEXT"] = "Um das rote Pulsieren des Spielerfensters beim Angreifen abzustellen, schalte in den Optionen (/fcui) unter Einheitenfenster Kampfleuchten ausblenden ein. Standardmäßig aus."
L["WN18_4_TITLE"] = "Zauberleisten"
L["WN18_4_TEXT"] = "Unterbrochene Zauber bei Ziel, Fokus und Namensplaketten werden jetzt rot und zeigen nur Unterbrochen, wie in Classic Era. Um zu sehen, wer unterbrochen hat, schalte in den Optionen (/fcui) unter Zauberleisten Unterbrecher nennen ein. Kanalisierte Zauber erscheinen grün."
L["WN18_5_TITLE"] = "Instanzschwierigkeit"
L["WN18_5_TEXT"] = "Die Schwierigkeitsflagge, die das Spiel in Dungeons und Schlachtzügen an der Minikarte zeigt, ist jetzt ausgeblendet. Um sie zurückzuholen, wähle in den Optionen (/fcui) unter Minikarte angezeigt oder beim Überfahren."
L["WN18_6_TITLE"] = "Klassisches Layout"
L["WN18_6_TEXT"] = "Die Haltbarkeitsfigur versteckt sich nicht mehr hinter den seitlichen Leisten, und Stärkungszauber sitzen an den Stellen aus Classic Era neben der Minikarte. Das Layout bietet außerdem die Interfacegröße aus Classic Era an, wenn deine abweicht."
L["WN18_7_TITLE"] = "Aussehen"
L["WN18_7_TEXT"] = "Menüs haben den schwarzen Hintergrund aus Classic Era, und Namensplaketten haben die Größe aus Classic Era. Der leere Teil der EP- und Rufleisten ist wie in Classic Era abgedunkelt; um das abzuschalten, entferne unter Klassische Leiste das Häkchen bei Abgedunkelte EP- und Rufleisten."
L["WN18_8_TITLE"] = "Fehlerbehebungen"
L["WN18_8_TEXT"] = "Erlernen funktioniert auch für Rezepte weit unten in der Liste eines Lehrers. Die Chatknöpfe bleiben auf jedem Chatreiter, und Umschalt-Klick verlinkt ein Talent im Chat. Die im Kampf geöffnete Weltkarte fängt keine Klicks mehr ab, und die roten Knöpfe des Bearbeitungsmodus bleiben beim Designwechsel ganz."
L["WN17_1_TITLE"] = "Fehler bei Namensplaketten"
L["WN17_1_TEXT"] = "Mit einem Design lösen die klassischen Namensplaketten keine Fehlermeldungen mehr aus."
L["WN17_2_TITLE"] = "Stärkungszauber des Ziels"
L["WN17_2_TEXT"] = "Stärkungszauber unter dem Ziel- und Fokusfenster erscheinen beim Zielwechsel jetzt gleich an ihrem Platz, ohne kurzes Springen."
L["WN17_3_TITLE"] = "Weltkarte im Kampf"
L["WN17_3_TEXT"] = "Die klassische Weltkarte sieht im Kampf geöffnet jetzt genauso aus wie außerhalb des Kampfes."
L["WN16_1_TITLE"] = "Aktionssymbole"
L["WN16_1_TEXT"] = "Mit einem Design werden die Symbole der Aktionstasten nicht mehr zufällig dunkel."
L["WN16_2_TITLE"] = "Kampfleuchten"
L["WN16_2_TEXT"] = "Mit Dicke Gesundheitsleisten über dem Namen leuchten das rote Kampfleuchten und das goldene Ausruhleuchten jetzt um das ganze Spielerfenster statt über der Gesundheitsleiste. Dicke Gesundheitsleisten sind standardmäßig aus; schalte sie in den Optionen (/fcui) unter Einheitenfenster ein."
L["WN16_3_TITLE"] = "Namensplaketten"
L["WN16_3_TEXT"] = "Mit ausgeschalteten klassischen Namensplaketten lösen die Namensplaketten des Spiels keine Fehlermeldungen mehr aus."
L["WN15_1_TITLE"] = "Bedrohung"
L["WN15_1_TEXT"] = "Die Bedrohung in Prozent aus Classic Era steht jetzt im Kampf über dem Ziel- und Fokusfenster. Das rote Leuchten um die Einheitenfenster ist jetzt standardmäßig aus; um es zurückzuholen, entferne in den Optionen (/fcui) unter Einheitenfenster das Häkchen bei Bedrohungsleuchten ausblenden."
L["WN15_2_TITLE"] = "Druidenmana"
L["WN15_2_TEXT"] = "In Bären- und Katzengestalt sehen Druiden ihr Mana jetzt in einer kleinen Leiste unter der Wut- oder Energieleiste."
L["WN15_3_TITLE"] = "Farbe der Gegner"
L["WN15_3_TEXT"] = "Standardmäßig aus. Schalte dazu in den Optionen (/fcui) unter Einheitenfenster Dicke Gesundheitsleisten ein und wähle unter Gesundheit von Gegnern Nach Gesinnung: Neutrale Gegner bekommen eine gelbe Leiste, feindliche eine rote."
L["WN15_4_TITLE"] = "Englischer Text"
L["WN15_4_TEXT"] = "Für ein Spiel in einer anderen Sprache: Die eigenen Texte dieses Addons können Teil für Teil auf Englisch erscheinen. Standardmäßig aus; schalte es in den Optionen (/fcui) unter Sonstiges, Englischer Text, ein."
L["WN15_5_TITLE"] = "Wer-Liste"
L["WN15_5_TEXT"] = "Der Pfeil oben in der letzten Spalte der Wer-Liste enthält jetzt die Klassen-, Volks- und Zonenfilter des Spiels. Eine Suche mit ein oder zwei Treffern bleibt im Fenster, statt im Chat zu landen."
L["WN15_6_TITLE"] = "Einfarbig"
L["WN15_6_TEXT"] = "Einfarbig malt die Grafik von Fenstern und Leisten in einer festen Farbe statt in Metall. Es behält jetzt die feinen Linien in Fenstern, um Listen, Fußleisten und Trenner, außer du schaltest auch Innere Ränder ausblenden ein. Beides ist standardmäßig aus: Schalte in den Optionen (/fcui) unter Aussehen erst Eigenes Design, dann Einfarbig ein."
L["WN15_7_TITLE"] = "Schlagtimer"
L["WN15_7_TEXT"] = "Die Schlagtimer können jetzt ohne das Aufblitzen nach jedem Schlag laufen: Entferne in den Optionen (/fcui) unter Schlagtimer das Häkchen bei Aufblitzen beim Schlag."
L["WN15_8_TITLE"] = "Namensplaketten"
L["WN15_8_TEXT"] = "Namen und kleine Zahlen auf Namensplaketten nutzen jetzt die schlichte Schrift aus Classic Era. Neu und standardmäßig aus: Gleiche Größe nah und fern hält jede Namensplakette gleich groß, wie in Classic Era; schalte es in den Optionen (/fcui) unter Namensplaketten ein."
L["WN15_9_TITLE"] = "Fenster"
L["WN15_9_TEXT"] = "Quest-, Gesprächs- und Händlerfenster und die Liste im Questlog haben jetzt den dünnen Rand aus Classic Era um ihren Inhalt, und das Charakterfenster zeigt auf jedem Reiter das Gesicht deines Charakters."
L["WN15_10_TITLE"] = "Korrekturen"
L["WN15_10_TEXT"] = "Mit einem Design nehmen Symbolränder, Porträtringe, Menüs und die Seitenpfeile beim Händler seine Farbe an, und Schieberegler bleiben sichtbar. Die Reiter des Charakterfensters reagieren jetzt dort, wo sie gezeichnet sind."
L["WN14_1_TITLE"] = "Controller"
L["WN14_1_TEXT"] = "Mit der Gamepad-Oberfläche öffnen sich das klassische Zauberbuch, die Talente und das Questlog in den eigenen Fenstern des Spiels, sodass ein Controller sich darin bewegen kann."
L["WN14_2_TITLE"] = "Design überall"
L["WN14_2_TEXT"] = "Mit einem Design nehmen auch die eigenen Teile des Spiels seine Farbe an, wo die klassischen aus sind: Minikarte, Einheitenfenster, Leisten, Fenster und die Tasten des Spielmenüs."
L["WN14_3_TITLE"] = "Dunkelheit"
L["WN14_3_TEXT"] = "Dunkel hat einen Schieberegler von Hellgrau bis Schwarz, mit einer Taste zurück zum Standard."
L["WN14_4_TITLE"] = "Einfarbig"
L["WN14_4_TEXT"] = "Einfarbig (Eigenes Design) zeigt die angehakten Teile in einer flachen Farbe, in denselben Formen."
L["WN14_5_TITLE"] = "Mikrotasten"
L["WN14_5_TEXT"] = "Mikrotasten ausblenden wirkt jetzt auch auf das eigene Mikromenü des Spiels bei ausgeschalteter klassischer Leiste und kann den Shop ausblenden."
L["WN14_6_TITLE"] = "Leisten 6 bis 8"
L["WN14_6_TEXT"] = "Leisten 6 bis 8 ausblenden ist entfallen: Die Aktionsleisten-Einstellungen des Spiels entscheiden."
L["WN14_7_TITLE"] = "Korrekturen"
L["WN14_7_TEXT"] = "Koordinaten: ausgeblendet und beim Überfahren wirken mit der Minikarte des Spiels, Minikartentasten anderer Addons nehmen das Design an, und der Rucksack eines Jägers zeigt freie Taschenplätze statt Munition."
L["WN13_1_TITLE"] = "Bedrohungsleuchten"
L["WN13_1_TEXT"] = "Bedrohungsleuchten ausblenden (Einheitenfenster) nimmt das rote Bedrohungsleuchten von den Einheitenfenstern. Die Bedrohungszahl des Spiels bleibt."
L["WN13_2_TITLE"] = "Questgegenstände"
L["WN13_2_TEXT"] = "Schlichte Questgegenstände (Taschenfenster) zeigt Questgegenstände in Taschen und Bank ohne Questrahmen."
L["WN13_3_TITLE"] = "Zahlen"
L["WN13_3_TEXT"] = "Zahlen ohne Trennzeichen (Einheitenfenster) entfernt die Tausendertrennzeichen aus großen Zahlen, auf den Leisten und im ganzen Spiel."
L["WN13_4_TITLE"] = "Aktionssymbole"
L["WN13_4_TEXT"] = "Mit einem Design zeigen sich Aktionssymbole wieder ganz, wie in Classic Era; nur ihr eigener Rand nimmt die Farbe des Designs an."
L["WN13_5_TITLE"] = "Deine Leisten"
L["WN13_5_TEXT"] = "Hat 0.14.0 deine Leisten verändert, kannst du sie über eine Chatzeile beim Einloggen wiederherstellen oder den klassischen Look wählen."
L["WN13_6_TITLE"] = "Sozialfenster"
L["WN13_6_TEXT"] = "Die Reiter Freunde und Schlachtzug stehen wie in Classic Era in ihrem dünnen Rahmen, und die Beschreibung des Schlachtzugreiters erscheint außerhalb eines Schlachtzugs wieder."
L["WN13_7_TITLE"] = "Korrekturen"
L["WN13_7_TEXT"] = "Beute an der Maus öffnet mit dem ersten Gegenstand unter dem Zeiger, Reiterbeschriftungen werden beim Darüberfahren weiß, und Klassisches Layout bringt das klassische Mikromenü und die Taschenplätze zurück."
L["WN12_1_TITLE"] = "Fenster"
L["WN12_1_TEXT"] = "Neben dem Schließen-Knopf jedes Fensters sitzen ein Schloss und ein Zurücksetzen: Ein entsperrtes Fenster zieht man an seinem Titel. Quest- und Gesprächsfenster, Sozialfenster, Gruppensuche und Berufebuch lassen sich in ClassicUI Forever Fenster platzieren und skalieren."
L["WN12_2_TITLE"] = "Schlagtimer"
L["WN12_2_TEXT"] = "Die Schlagtimer des Spiels im Stil der 1.x-Zauberleiste, mit einer Farbe pro Hand und einem Aufblitzen bei jedem Schlag. Farben und Rahmenstärke stellt man in den Optionen ein."
L["WN12_3_TITLE"] = "Dicke Gesundheitsleisten"
L["WN12_3_TEXT"] = "Eine höhere Gesundheitsleiste auf dem Spieler-, Ziel- und Fokusfenster, über dem Namen oder über dem Mana (Einheitenfenster). Dort sind auch Namensfeld in Klassenfarbe und Namensgröße neu."
L["WN12_4_TITLE"] = "Greifen"
L["WN12_4_TEXT"] = "Die Greifen lassen sich im Bearbeitungsmodus des Spiels ziehen, skalieren oder ausblenden. Mit eingeschaltetem Einrasten richten sie sich an den Leisten aus und kehren an ihren Platz zurück."
L["WN12_5_TITLE"] = "Schadensmesser"
L["WN12_5_TEXT"] = "Der Schadensmesser im 1.x-Rahmen mit klassischen Knöpfen und einem Marmor- oder Talentbaum-Hintergrund, den man verschieben kann."
L["WN12_6_TITLE"] = "Sprachen"
L["WN12_6_TEXT"] = "ClassicUI Forever gibt es jetzt auf Deutsch, Französisch, Spanisch und Italienisch."
L["WN12_7_TITLE"] = "Optionen"
L["WN12_7_TEXT"] = "Neue Reiter FAQ und Support, eine Eigene Farbe für das Thema und eine Suche, die eine Einstellung unter mehr Namen findet."
L["WN12_8_TITLE"] = "Ressourcenanzeige"
L["WN12_8_TEXT"] = "Die persönliche Ressourcenanzeige in 1.x-Leisten und im alten Namensplakettenrahmen, mit der Einstellung Leistenabstand."
L["WN12_9_TITLE"] = "Klassische Leiste"
L["WN12_9_TEXT"] = "Taschenplätze in klassischer Größe, jede Mikrotaste lässt sich ausblenden, die Hilfe-Taste steht wieder am Ende des Mikromenüs, und Band trägt Leisten 2 und 3 hält diese Leisten auf dem Band."
L["WN12_10_TITLE"] = "Minikarte und Chat"
L["WN12_10_TEXT"] = "Koordinaten sowie ein ausblendbarer Rand und Kopf an der Minikarte, das Auge der Gruppensuche daran, wenn ihre Mikrotaste ausgeblendet ist, und jede Chattaste lässt sich einzeln ausblenden."
L["WN12_11_TITLE"] = "Korrekturen"
L["WN12_11_TEXT"] = "Leisten springen nach dem Ziehen im Bearbeitungsmodus nicht mehr an den oberen Bildschirmrand, Leiste 1 bewegt sich im Bearbeitungsmodus mit den Pfeiltasten, die EP-Leiste erscheint nach dem Einloggen im Kampf nicht mehr doppelt, und Beuteseiten wiederholen keine Gegenstände mehr."
L["WN12_12_TITLE"] = "Kleinere Korrekturen"
L["WN12_12_TEXT"] = "Begleiter- und Gruppenzahlen passen in ihre Leisten, das Mikromenü springt beim Ziehen nicht mehr, die Latenzleiste behält ihren Rahmen, und die Tipps der Mikrotasten erscheinen einmal und mit der richtigen Questgrenze."
L["WN11_1_TITLE"] = "Chat"
L["WN11_1_TEXT"] = "Chattasten ausblenden lässt den Chat am Bildschirmrand sitzen, und Chat-Bildlaufleiste behält die Bildlaufleiste von WoW Forever (Chattasten)."
L["WN11_2_TITLE"] = "Queststufen"
L["WN11_2_TEXT"] = "Queststufen (Quests) zeigt die Stufe jeder Quest auf der Karte, in der Questverfolgung und im Questlog, im Einklang mit dem eigenen Filter der Karte."
L["WN11_3_TITLE"] = "Dunkles Design"
L["WN11_3_TEXT"] = "Rechtsklickmenüs, Minikartentasten von Addons, die Zoomtasten, Uhr und das Tag-und-Nacht-Symbol übernehmen das Design, und Aktionssymbole zeigen keinen hellen Rand."
L["WN11_4_TITLE"] = "Korrekturen"
L["WN11_4_TEXT"] = "Keine doppelte Queststufe in der Questverfolgung, keine Fehler durch Rechtsklickmenüs in Dungeons, und das Menü des Ziels bleibt auf dem Bildschirm."
L["WN10_1_TITLE"] = "Minikarte"
L["WN10_1_TEXT"] = "Jedes Teil der Minikarte kann erscheinen, nur beim Überfahren erscheinen oder ausgeblendet sein (Minikarte in den Optionen), und Hinein- und Herauszoomen bewegen sich in ClassicUI Forever Fenster einzeln um den Ring."
L["WN10_2_TITLE"] = "Mikromenü"
L["WN10_2_TEXT"] = "Die Beschreibungen von Classic Era in den Tooltips der Mikrotasten, und Mikrotasten ausblenden nimmt einzelne Tasten aus dem Menü (Klassische Leiste)."
L["WN10_3_TITLE"] = "Schlüsselbund"
L["WN10_3_TEXT"] = "Öffnet sich auch ohne Schlüssel, in einem eigenen Fenster, in der Grafik von Classic Era."
L["WN10_4_TITLE"] = "Neue Optionen"
L["WN10_4_TEXT"] = "Haltungsleiste ausblenden (Klassische Leiste), Größe des Namenstexts (Namensplaketten) und Einheiten-Tooltip auf Leisten (Einheitenfenster)."
L["WN10_5_TITLE"] = "Korrekturen"
L["WN10_5_TEXT"] = "Bildlaufpfeile werden grau, wenn nichts zu scrollen ist, das Questlog hebt wie in Classic Era hervor, Zuletzt online in der Gilde sortiert richtig und das Makrofenster öffnet sich neben dem Zauberbuch."
L["WN10_6_TITLE"] = "Kleinere Korrekturen"
L["WN10_6_TEXT"] = "Talentpfeile, der Gildenreiter ohne Gilde, Seitenpfeile über der Karte, die Tasche für Addontasten und kürzere Layoutabfragen."
L["WN9_1_TITLE"] = "Klassische Weltkarte"
L["WN9_1_TEXT"] = "Die kleine Karte von Classic Era, mit der Questliste der Karte in einem eigenen Bereich daneben und Belohnungen nach dem Questtext. Kartennavigationsleiste unter Karte in den Optionen bringt das Kartenlayout des Spiels zurück."
L["WN9_2_TITLE"] = "Neue Optionen"
L["WN9_2_TEXT"] = "Questtaste der Karte ausblenden (Karte), Leisten in klassischer Größe (Klassische Leiste) und Wackeln bei Unterbrechung (Zauberleisten)."
L["WN9_3_TITLE"] = "Klassischer Look"
L["WN9_3_TEXT"] = "Rechtsklickmenüs, Auswahllisten, das Kontaktefenster, die Gruppensuche, die Wer-Liste und die Gildenliste folgen Classic Era; das Einstellungsfenster übernimmt den Look des heutigen Classic-Era-Clients, und Ignorierliste und Anprobe den klassischen Look."
L["WN9_4_TITLE"] = "Bearbeitungsmodus"
L["WN9_4_TEXT"] = "Das Zauberbuch lässt sich in ClassicUI Forever Fenster verschieben und in der Größe ändern."
L["WN9_5_TITLE"] = "Leisten und Questverfolgung"
L["WN9_5_TEXT"] = "Die Leisten 4 und 5 behalten ihren Platz am Bildschirmrand, und die Questverfolgung liegt nicht mehr über ihnen."
L["WN9_6_TITLE"] = "Korrekturen"
L["WN9_6_TEXT"] = "Neutrale NSCs zeigen ihre Stufe statt eines Totenkopfs, und ein Klick auf die Leisten eines Einheitenfensters wählt wieder ein Ziel."
L["WN9_7_TITLE"] = "Fenster und Reiter"
L["WN9_7_TEXT"] = "Händler-, Post-, Gildenurkunden- und Wappenrockfenster sowie viele andere Fenster und Reiter richten sich nach Classic Era aus; Escape schließt das Gildenurkundenfenster."
L["WN8_1_TITLE"] = "Greifen über den Leisten"
L["WN8_1_TEXT"] = "Aktiviere Greifen über den Leisten unter Klassische Leiste in den Optionen, um die Greifen vor die Leisten 2 und 3 zu zeichnen."
L["WN8_2_TITLE"] = "Fenster öffnen beim Tastendruck"
L["WN8_2_TEXT"] = "Die Tasten für Zauberbuch, Berufe, Talente, Gilde und Questlog sowie Escape reagieren beim Drücken, wie die eigenen Fenster des Spiels."
L["WN8_3_TITLE"] = "Korrekturen"
L["WN8_3_TEXT"] = "Zauber lassen sich wieder auf Aktionsleiste 1 ziehen, der Gebietsname ist auf der Minikartenleiste zentriert, wo immer der Kalender sitzt, und die Reiter und Begleiterbefehle des Zauberbuchs sehen richtig aus."
L["WN7_1_TITLE"] = "Klassischer Tastentext"
L["WN7_1_TEXT"] = "Tastennamen auf den Aktionstasten haben die Größe und Umrandung von Classic Era. Größe des Tastentexts unter Tastenstil in den Optionen macht sie größer oder kleiner."
L["WN7_2_TITLE"] = "Kalenderplätze"
L["WN7_2_TEXT"] = "Der Kalender ist ein kleines Quadrat beim Gebietsnamen; setz ihn auf den Ring oder hinter das Tag-und-Nacht-Symbol unter Kalendertaste in den Optionen. Markiere Kalender unter Minikarte in ClassicUI Forever Fenster im Bearbeitungsmodus, um ihn zu verschieben oder in der Größe zu ändern."
L["WN6_1_TITLE"] = "Kalendertaste"
L["WN6_1_TEXT"] = "Der Kalender sitzt unter dem Tag-und-Nacht-Symbol an der Minikarte. Um ihn auszublenden, entferne das Häkchen bei Kalendertaste unter Minikarte in den Optionen."
L["WN5_1_TITLE"] = "Korrekturen"
L["WN5_1_TEXT"] = "Die Markierung für neue Spieler in der Gruppensuche richtet sich an den Rollensymbolen aus. Details im vollständigen Änderungsprotokoll."
L["WN4_1_TITLE"] = "Korrekturen"
L["WN4_1_TEXT"] = "Reiter nehmen die Maus am Reiter selbst an, ein aus dem Zauberbuch gewirkter Beruf schließt das Buch im Kampf, und der Kopf des Beutefensters ist sauber. Details im vollständigen Änderungsprotokoll."
L["WN3_1_TITLE"] = "Teile der klassischen Leiste"
L["WN3_1_TEXT"] = "Classic hatte keine Berufetaste und keine Reagenzientasche, daher ist die Berufetaste aus dem Mikromenü (Berufe öffnen sich aus dem Zauberbuch) und die Reagenzientasche ist eine kleine runde Taste beim Überfahren. Die Leisten 2 und 3 passen wieder zwischen die Greifen. Beides sind Zeilen unter Klassische Leiste in den Optionen."
L["WN2_1_TITLE"] = "Fenster-Bearbeitungsmodus"
L["WN2_1_TEXT"] = "Markiere Fenster im Bearbeitungsmodus, um Charakterfenster, Zauberbuch, Talente, Questlog, Berufe und Karte zu verschieben und in der Größe zu ändern."
L["WN2_2_TITLE"] = "Profile"
L["WN2_2_TEXT"] = "Ein Reiter Profile in den Optionen speichert benannte Einstellungen pro Charakter."
L["WN2_3_TITLE"] = "Bronze oder Dunkel"
L["WN2_3_TEXT"] = "Das eigene Design gibt es in der Bronze von Forever oder in dunklem Anthrazit. Siehe die Option Eigenes Design."
L["WN2_4_TITLE"] = "Klassische Leiste"
L["WN2_4_TEXT"] = "Die Leisten werden standardmäßig nicht mehr verkleinert. Die Leiste trägt jetzt Latenzleiste, Schlüsselbund und Reagenzientasche wie in Classic; jedes davon lässt sich im Bearbeitungsmodus verschieben oder unter Klassische Leiste in den Optionen ausblenden."
L["WN2_5_TITLE"] = "Minikartentasten"
L["WN2_5_TEXT"] = "Die Minikartentasten anderer Addons können sich hinter einer Taste am Ring sammeln. Siehe die Option Addontasten sammeln."
L["WN2_6_TITLE"] = "Optionen"
L["WN2_6_TEXT"] = "Abschnitte für Quests und Karte sowie neue Zeilen für den Kartenrahmen, das Beutefenster, Beutewürfe, das Ausblenden der Zielverfolgung des Spiels, die Berufetaste und den Tastentext."
L["WN2_7_TITLE"] = "Klassisches Layout zurücksetzen"
L["WN2_7_TEXT"] = "Setzt Fenster, Questverfolgung, Greifen, Leistenteile und Layouteinstellungen auf einmal zurück."
